using System; using System.IO; using Mono.Cecil; using System.Linq;
class DumpThemes { static void Main(string[] args) { Directory.CreateDirectory(args[1]); using(var module=ModuleDefinition.ReadModule(args[0])) { var method=module.Types.Single(x=>x.FullName=="ProtonVPN.Client.App").Methods.Single(x=>x.Name=="LoadTypographyResourceDictionary"); int i=0; foreach(var text in method.Body.Instructions.Select(x=>x.Operand).OfType<string>().Where(x=>x.StartsWith("<ResourceDictionary"))) File.WriteAllText(Path.Combine(args[1], "theme-"+(i++)+".xaml"),text); Console.WriteLine(i+" generated theme dictionaries extracted."); } } }
